class_basic.code:
class P:
    def __init__(self, x):
        self.x = x
    def __repr__(self):
        return f'P({self.x})'
    def double(self):
        return self.x * 2
p = P(3)
print(p, p.double(), [p])

class_inherit_super.code:
class A:
    def __init__(self, x):
        self.x = x
class B(A):
    def __init__(self, x, y):
        super().__init__(x)
        self.y = y
b = B(1, 2)
print(b.x, b.y, isinstance(b, A))

class_dunder_lt.code:
